  const context = await browser.newContext({ reducedMotion: reducedMotion ? 'reduce' : 'no-preference' });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });

  await page.goto('http://localhost:3311/', { waitUntil: 'networkidle' });
  await page.screenshot({ path: `/tmp/vt-test/${label}-1-grid.png` });

  // Check native support is being exercised
  const supportsVT = await page.evaluate(() => typeof document.startViewTransition === 'function');

  // Click the first product link and capture mid-transition + settled frames
  const link = page.locator('a.product-card').first();
  await link.click();

  // Grab a frame shortly after click (mid-transition), then settled.
  await page.waitForTimeout(80);
  await page.screenshot({ path: `/tmp/vt-test/${label}-2-mid.png` });
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(600);
  await page.screenshot({ path: `/tmp/vt-test/${label}-3-detail.png` });

  await page.goBack();
  await page.waitForTimeout(80);
  await page.screenshot({ path: `/tmp/vt-test/${label}-4-back-mid.png` });
  await page.waitForTimeout(600);
  await page.screenshot({ path: `/tmp/vt-test/${label}-5-back-settled.png` });

  console.log(label, 'supportsViewTransition:', supportsVT, 'errors:', errors);
  await context.close();
}

