  await link.click();

  const samples = [];
  const start = Date.now();
  while (Date.now() - start < 900) {
    const info = await page.evaluate(() => {
      const anims = document.getAnimations();
      return {
        t: performance.now(),
        count: anims.length,
        names: anims.map((a) => a.animationName || a.constructor.name).slice(0, 10),
        h1: document.querySelector('h1')?.textContent,
      };
    }).catch(() => null);
    if (info) samples.push({ ...info, elapsed: Date.now() - start });
    await page.waitForTimeout(40);
  }
  console.log(label, JSON.stringify(samples.filter((s) => s.count > 0 || true).map(s => ({e: s.elapsed, c: s.count, n: s.names, h1: s.h1}))));

  await context.close();
}

await run(false, 'motion');
